    res = [[bg_val] * W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            d_tl = r + c
            d_tr = r + (W - 1 - c)
            d_bl = (H - 1 - r) + c
            d_br = (H - 1 - r) + (W - 1 - c)

            # Closest source
            sources = [('tl', d_tl), ('tr', d_tr), ('bl', d_bl), ('br', d_br)]
            closest = min(sources, key=lambda x: x[1])
            src_name, _ = closest

            if src_name == 'tl':
                if (r + c) % 2 == 0:
                    res[r][c] = tl
            elif src_name == 'tr':
                if (r + (W - 1 - c)) % 2 == 0:
                    res[r][c] = tr
            elif src_name == 'bl':
                if ((H - 1 - r) + c) % 2 == 0:
                    res[r][c] = bl
            elif src_name == 'br':
                if ((H - 1 - r) + (W - 1 - c)) % 2 == 0:
                    res[r][c] = br

    return res
